var dayStart = (d) => new Date(d.getFullYear(), d.getMonth(), d.getDate()).getTime();
var DAY = 864e5;
function seasonStatus(now) {
  const y = now.getFullYear();
  const opens = new Date(y, 8, 1).getTime();
  const closes = new Date(y, 11, 1).getTime();
  const t = dayStart(now);
  if (t >= opens && t <= closes) {
    const days2 = Math.round((closes - t) / DAY);
    return {
      open: true,
      days: days2,
      text: days2 === 0 ? "Season closes today (Dec 1)" : `Season open: ${days2} day${days2 === 1 ? "" : "s"} left (closes Dec 1)`
    };
  }
  const next = t < opens ? opens : new Date(y + 1, 8, 1).getTime();
  const days = Math.round((next - t) / DAY);
  return { open: false, days, text: `Season closed: opens Sep 1 (${days} days). Scout, don't dig.` };
}

